// SystemVerilog example demonstrating separate clocks for timing generation and functional logic
module timed_counter #(
  parameter int unsigned DIV_FACTOR = 25_000_000
) (
  input  logic sys_clk,
  input  logic rst_n,
  input  logic enable,
  output logic [7:0] event_count
);

  // Clock divider to generate a slower clock
  logic [$clog2(DIV_FACTOR)-1:0] div_cnt;
  logic slow_clk;

  // Timing generation in system clock domain
  always_ff @(posedge sys_clk or negedge rst_n) begin
    if (!rst_n) begin
      div_cnt  <= '0;
      slow_clk <= 1'b0;
    end else if (enable) begin
      if (div_cnt == DIV_FACTOR-1) begin
        div_cnt  <= '0;
        slow_clk <= ~slow_clk;
      end else begin
        div_cnt <= div_cnt + 1;
      end
    end
  end

  // Functional logic in derived clock domain
  always_ff @(posedge slow_clk or negedge rst_n) begin
    if (!rst_n) begin
      event_count <= '0;
    end else if (enable) begin
      event_count <= event_count + 1;
    end
  end

endmodule

// SystemVerilog example: async signal in ALL relevant blocks
module async_timer #(
  parameter int unsigned DIV_FACTOR = 1000
) (
  input  logic clk,
  input  logic reset,
  input  logic load,           // Asynchronous load signal
  input  logic [7:0] load_val, // Value to load
  output logic [7:0] counter
);

  logic [$clog2(DIV_FACTOR)-1:0] divider;
  logic pulse;

  // Clock divider - INCLUDES 'posedge load' for async behavior
  always_ff @(posedge clk or posedge reset or posedge load) begin
    if (reset) begin
      divider <= '0;
      pulse <= 1'b0;
    end else if (load) begin
      divider <= '0;  // Reset divider when loading
      pulse <= 1'b0;
    end else begin
      if (divider == DIV_FACTOR-1) begin
        divider <= '0;
        pulse <= 1'b1;
      end else begin
        divider <= divider + 1;
        pulse <= 1'b0;
      end
    end
  end

  // Counter - ALSO includes 'posedge load' for async behavior
  always_ff @(posedge pulse or posedge reset or posedge load) begin
    if (reset) begin
      counter <= '0;
    end else if (load) begin
      counter <= load_val;  // Load new value immediately
    end else begin
      counter <= counter + 1;
    end
  end

endmodule

// DEBUGGING INSIGHT: If adding 'posedge load' to just the counter block
// fixes load but breaks timing, it means the divider also needs 'posedge load'.
// The solution is adding it to BOTH blocks, not choosing between them.
